/*
 * utils_hdc1080.c
 *
 *      Author: Kishan K. Mandal
 *
 *  @brief Thread-safe RTOS wrapper implementation for the HDC1080 sensor.
 *         Encapsulates the HDC1080 handle and a FreeRTOS Mutex with Priority
 *         Inheritance to prevent I2C1 bus contention and register pointer
 *         overwrite during the 15 ms sensor conversion window.
 */

#include "utils_hdc1080.h"
#include "FreeRTOS.h"
#include "semphr.h"

/* External I2C1 peripheral handle generated by CubeMX in main.c */
extern I2C_HandleTypeDef hi2c1; // Defined in main.c

static HDC1080_HandleTypeDef hdc1080;
static SemaphoreHandle_t hdc1080_i2c_mutex = NULL;

/**
 * @brief Initializes the HDC1080 hardware and allocates the I2C1 FreeRTOS Mutex.
 */
void init_HDC1080(void)
{
    /* 1. Initialize the HDC1080 sensor on I2C1 FIRST. */
    if (HDC1080_Init(&hdc1080, &hi2c1, HDC1080_TEMP_RES_14BIT, HDC1080_HUM_RES_14BIT) != HAL_OK) {
        Error_Handler();
    }

    /* 2. Create the Mutex for thread-safe I2C1 serialization across RTOS tasks */
    if (hdc1080_i2c_mutex == NULL) {
        hdc1080_i2c_mutex = xSemaphoreCreateMutex();
    }

    /* Halt here if FreeRTOS heap was too small or mutex creation failed */
    configASSERT(hdc1080_i2c_mutex != NULL);
}

/**
 * @brief Acquires the I2C1 mutex, performs a full temperature conversion + read
 *        sequence, and releases the mutex.
 */
bool get_Temp_data(float *temperature)
{
    /* Defensive check against NULL pointer dereference */
    if (temperature == NULL) {
        return false;
    }

    /* Ensure init_HDC1080() was called prior to task execution */
    configASSERT(hdc1080_i2c_mutex != NULL);

    HAL_StatusTypeDef status = HAL_ERROR;

    /* Lock the I2C1 bus before starting the temperature transaction.
     * If another task is currently reading humidity, this task enters the
     * Blocked state (0% CPU usage) until the bus is released. */
    if (xSemaphoreTake(hdc1080_i2c_mutex, portMAX_DELAY) == pdTRUE) {

        status = HDC1080_ReadTemperature(&hdc1080, temperature);

        /* Unlock the I2C1 bus only AFTER reading the 2 temperature bytes */
        xSemaphoreGive(hdc1080_i2c_mutex);
    }

    return (status == HAL_OK);
}

/**
 * @brief Acquires the I2C1 mutex, performs a full humidity conversion + read
 *        sequence, and releases the mutex.
 */
bool get_Humidity_data(float *humidity)
{
    /* Defensive check against NULL pointer dereference */
    if (humidity == NULL) {
        return false;
    }

    /* Ensure init_HDC1080() was called prior to task execution */
    configASSERT(hdc1080_i2c_mutex != NULL);

    HAL_StatusTypeDef status = HAL_ERROR;

    /* Lock the I2C1 bus before starting the humidity transaction */
    if (xSemaphoreTake(hdc1080_i2c_mutex, portMAX_DELAY) == pdTRUE) {

        status = HDC1080_ReadHumidity(&hdc1080, humidity);

        /* Unlock the I2C1 bus only AFTER reading the 2 humidity bytes */
        xSemaphoreGive(hdc1080_i2c_mutex);
    }

    return (status == HAL_OK);
}
